// Edit these values in n8n after importing.
const cfg = {
  recallWebhookSecret: '',                        // Recall.ai signing secret (whsec_...). Preferred: requests are verified by signature
  recallWebhookToken: 'PASTE_A_RANDOM_TOKEN',     // used only while recallWebhookSecret is empty: add ?token=<this> to the endpoint URL
  recallBaseUrl: 'https://us-east-1.recall.ai',    // same region URL as in the booking workflow
  handshakeRecordingsUrl: 'https://handshake.designinnsaeit.com/api/recordings',
};
const item = $input.first();
return [{ json: { ...item.json, ...cfg }, binary: item.binary }];

// Pure-JS SHA-256 and HMAC, pasted into the n8n Code nodes so signature checks work on any n8n plan
// (n8n Cloud may not allow require('crypto')). Verified against node:crypto in hmac-sha256.test.mjs.
const SHA256_K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

function sha256(msg) {
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const len = msg.length;
  const padded = new Uint8Array(((len + 9 + 63) >> 6) << 6);
  padded.set(msg);
  padded[len] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(padded.length - 8, Math.floor((len * 8) / 0x100000000));
  view.setUint32(padded.length - 4, (len * 8) >>> 0);
  const w = new Uint32Array(64);
  for (let off = 0; off < padded.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const a = w[i - 15];
      const b = w[i - 2];
      const s0 = ((a >>> 7) | (a << 25)) ^ ((a >>> 18) | (a << 14)) ^ (a >>> 3);
      const s1 = ((b >>> 17) | (b << 15)) ^ ((b >>> 19) | (b << 13)) ^ (b >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + SHA256_K[i] + w[i]) >>> 0;
      const S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + t1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0;
    H[1] = (H[1] + b) >>> 0;
    H[2] = (H[2] + c) >>> 0;
    H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0;
    H[5] = (H[5] + f) >>> 0;
    H[6] = (H[6] + g) >>> 0;
    H[7] = (H[7] + h) >>> 0;
  }
  const out = new Uint8Array(32);
  const outView = new DataView(out.buffer);
  H.forEach((v, i) => outView.setUint32(i * 4, v));
  return out;
}

function hmacSha256Bytes(key, msg) {
  let k = typeof key === 'string' ? new TextEncoder().encode(key) : key;
  if (k.length > 64) k = sha256(k);
  const inner = new Uint8Array(64 + msg.length);
  const outer = new Uint8Array(64 + 32);
  for (let i = 0; i < 64; i++) {
    const byte = k[i] || 0;
    inner[i] = byte ^ 0x36;
    outer[i] = byte ^ 0x5c;
  }
  inner.set(msg, 64);
  outer.set(sha256(inner), 64);
  return sha256(outer);
}

function hmacSha256Hex(key, msg) {
  return Array.from(hmacSha256Bytes(key, msg), (x) => x.toString(16).padStart(2, '0')).join('');
}

const BASE64_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function base64Encode(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] || 0) << 8) | (bytes[i + 2] || 0);
    out += BASE64_CHARS[(n >> 18) & 63] + BASE64_CHARS[(n >> 12) & 63];
    out += i + 1 < bytes.length ? BASE64_CHARS[(n >> 6) & 63] : '=';
    out += i + 2 < bytes.length ? BASE64_CHARS[n & 63] : '=';
  }
  return out;
}

function base64Decode(text) {
  const clean = text.replace(/[^A-Za-z0-9+/]/g, '');
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4));
  let bits = 0;
  let acc = 0;
  let j = 0;
  for (const ch of clean) {
    acc = (acc << 6) | BASE64_CHARS.indexOf(ch);
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[j++] = (acc >> bits) & 255;
    }
  }
  return out;
}

// Recall.ai (and Svix) sign webhooks as HMAC-SHA256 over "<id>.<timestamp>.<body>", keyed with the
// base64 part of a "whsec_..." secret, sent as "v1,<base64>" (several, space separated, during rotation).
// Older Recall workspaces send the same thing under svix-* header names.
function verifyStandardWebhook(secret, headers, rawBytes, nowMs) {
  const id = headers['webhook-id'] || headers['svix-id'];
  const timestamp = headers['webhook-timestamp'] || headers['svix-timestamp'];
  const signatures = headers['webhook-signature'] || headers['svix-signature'];
  if (!id || !timestamp || !signatures) return false;
  const seconds = Number(timestamp);
  if (!Number.isFinite(seconds) || Math.abs(nowMs / 1000 - seconds) > 300) return false;
  const key = base64Decode(secret.startsWith('whsec_') ? secret.slice(6) : secret);
  const prefix = new TextEncoder().encode(id + '.' + timestamp + '.');
  const message = new Uint8Array(prefix.length + rawBytes.length);
  message.set(prefix);
  message.set(rawBytes, prefix.length);
  const expected = base64Encode(hmacSha256Bytes(key, message));
  return String(signatures)
    .split(' ')
    .some((part) => {
      const [version, signature] = part.split(',');
      return version === 'v1' && Boolean(signature) && timingSafeEqualStr(signature, expected);
    });
}

function timingSafeEqualStr(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const cfg = $('Config').first().json;
const hook = $input.first().json;
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');

if (cfg.recallWebhookSecret) {
  if (!verifyStandardWebhook(cfg.recallWebhookSecret, hook.headers || {}, raw, Date.now())) {
    throw new Error('Invalid Recall.ai webhook signature, ignoring request');
  }
} else {
  if (!cfg.recallWebhookToken || cfg.recallWebhookToken.startsWith('PASTE_')) {
    throw new Error('Config node: set recallWebhookSecret (preferred) or recallWebhookToken first');
  }
  if ((hook.query || {}).token !== cfg.recallWebhookToken) throw new Error('Bad token on the Recall webhook, ignoring request');
}

const body = JSON.parse(new TextDecoder().decode(raw));
if (body.event !== 'bot.done') return [];
const bot = (body.data || {}).bot || {};
return [{ json: { botId: bot.id, metadata: bot.metadata || {} } }];

const bot = $input.first().json;
const rec = (bot.recordings || [])[0];
const url = rec && rec.media_shortcuts && rec.media_shortcuts.transcript && rec.media_shortcuts.transcript.data && rec.media_shortcuts.transcript.data.download_url;
if (!url) throw new Error('No transcript yet for bot ' + bot.id + ', re-run this execution in a few minutes');
const meta = $('Only bot.done').first().json.metadata;
return [{ json: { url, botId: bot.id, title: meta.title, startTime: meta.startTime } }];

const prev = $('Find transcript URL').first().json;
const segments = $input.all().map((i) => i.json);
const lines = [];
let last = null;
let lastEnd = 0;
for (const s of segments) {
  const name = (s.participant && s.participant.name) || 'Speaker';
  const words = s.words || [];
  const text = words.map((w) => w.text).join(' ').trim();
  if (!text) continue;
  const end = words.length ? (words[words.length - 1].end_timestamp || {}).relative || 0 : 0;
  if (end > lastEnd) lastEnd = end;
  if (name === last) lines[lines.length - 1] += ' ' + text;
  else lines.push(name + ': ' + text);
  last = name;
}
if (!lines.length) throw new Error('Transcript for bot ' + prev.botId + ' was empty');
return [{ json: {
  clientRef: 'recall:' + prev.botId,
  source: 'recall',
  transcriptSource: 'recall',
  title: prev.title || 'Recall meeting',
  transcript: lines.join('\n'),
  recordedAt: prev.startTime,
  durationSec: lastEnd ? Math.round(lastEnd) : undefined,
} }];
